#!/bin/bash
# ============================================================================
# fix_payment_edit_mode_switch_ux.sh
#
# Fixes the actual root cause behind the repeated Cash+UPI double-counted
# refund errors (Satya Pal Singh, Utkarsh Prakash): the "Add mode" button
# in the Receipt Register edit form looks like the way to CHANGE a
# payment's mode (e.g. Cash -> UPI), but it's actually for SPLITTING one
# payment across multiple modes. Clicking "Add mode" to add UPI without
# removing the original Cash row leaves both rows in place, so the total
# doubles and the save is correctly rejected by the server-side safety
# checks -- but with no way for the user to see why before hitting Save.
#
# NOTE: The database-side concurrency/locking fix (edit_payment_clerical
# SQL function) was already applied directly to both Supabase projects in
# an earlier step and needs no further changes -- it was working
# correctly the whole time; this was a UX/workflow issue, not a data bug.
#
#   MODIFIED: app/(main)/payments/receipt/receipt-tab.js
#     - Clarified info banner: change mode by selecting a new option in
#       the existing row; "Add mode" (relabeled "Split into another
#       mode") is only for splitting the payment across multiple modes.
#     - Live running total shown under the mode rows as you type/change
#       them (green when it matches the payment total, red with a clear
#       instruction when it doesn't) -- no need to hit Save to find out.
#     - Save Correction button is now disabled outright whenever the
#       live total doesn't match, so a mismatched split can no longer
#       even be submitted.
#
# Run this from the root of your veda-hmis repo in GitHub Codespaces.
# ============================================================================

set -e

echo "==> Payment edit mode-switch UX fix"
echo ""

if [ ! -f "package.json" ] || [ ! -d "app" ]; then
  echo "ERROR: This doesn't look like the veda-hmis repo root (no package.json / app dir found)."
  echo "cd into your repo root and re-run this script."
  exit 1
fi

echo "==> Overwriting app/(main)/payments/receipt/receipt-tab.js"
echo "" | base64 -d > "app/(main)/payments/receipt/receipt-tab.js"

echo ""
echo "==> File written. Verifying build..."
if command -v npm >/dev/null 2>&1; then
  npm run build || { echo "BUILD FAILED -- check output above before pushing."; exit 1; }
else
  echo "npm not found -- skipping build verification, run 'npm run build' manually."
fi

echo ""
echo "==> Done. Review changes with: git status && git diff"
echo "==> To deploy, run:"
echo "    git add -A"
echo '    git commit -m "Fix payment edit UX: clarify mode-change vs split, add live total, disable Save on mismatch"'
echo "    git push"
